// kaleid TUI — design canvas app
// Mounts a DesignCanvas with 5 theme sections × 2 artboards (Resume + Chat).
// Tweaks panel exposes font size + line height controls and a per-canvas
// "show ASCII box" toggle.

const { useState } = React;

const KALEID_TWEAK_DEFAULTS = /*EDITMODE-BEGIN*/{
  "fontSize": 14,
  "lineHeight": 1.55,
  "asciiBoxOverride": "auto"
}/*EDITMODE-END*/;

const ARTBOARD_W = 1280;
const ARTBOARD_H = 760;

function App() {
  const t = useTweaks(KALEID_TWEAK_DEFAULTS);
  const themes = window.TUI_THEMES;
  const themeOrder = ['aurora', 'monolith', 'blueprint', 'daylight', 'spectrum'];

  const resolveBox = (theme) => {
    if (t.tweaks.asciiBoxOverride === 'on') return true;
    if (t.tweaks.asciiBoxOverride === 'off') return false;
    return theme.boxDrawing === 'full';
  };

  return (
    <React.Fragment>
      <DesignCanvas>
        {themeOrder.map((key) => {
          const theme = themes[key];
          return (
            <DCSection
              id={key}
              key={key}
              title={theme.name}
              subtitle={theme.blurb}
            >
              <DCArtboard
                id={key + '-resume'}
                label="Resume"
                width={ARTBOARD_W}
                height={ARTBOARD_H}
              >
                <ResumeScreen
                  theme={theme}
                  fontSize={t.tweaks.fontSize}
                  lineHeight={t.tweaks.lineHeight}
                  showBox={resolveBox(theme)}
                />
              </DCArtboard>
              <DCArtboard
                id={key + '-chat'}
                label="Main chat"
                width={ARTBOARD_W}
                height={ARTBOARD_H}
              >
                <ChatScreen
                  theme={theme}
                  fontSize={t.tweaks.fontSize}
                  lineHeight={t.tweaks.lineHeight}
                  showBox={resolveBox(theme)}
                />
              </DCArtboard>
            </DCSection>
          );
        })}
      </DesignCanvas>

      <TweaksPanel title="Tweaks" initialPosition={{ right: 24, bottom: 24 }}>
        <TweakSection title="Typography">
          <TweakSlider
            label="Font size"
            value={t.tweaks.fontSize}
            onChange={(v) => t.setTweak('fontSize', v)}
            min={11}
            max={18}
            step={1}
            unit="px"
          />
          <TweakSlider
            label="Line height"
            value={t.tweaks.lineHeight}
            onChange={(v) => t.setTweak('lineHeight', v)}
            min={1.2}
            max={1.9}
            step={0.05}
          />
        </TweakSection>
        <TweakSection title="Frame chrome">
          <TweakRadio
            label="ASCII box drawing"
            value={t.tweaks.asciiBoxOverride}
            onChange={(v) => t.setTweak('asciiBoxOverride', v)}
            options={[
              { value: 'auto', label: 'theme default' },
              { value: 'on',   label: 'always on' },
              { value: 'off',  label: 'never' },
            ]}
          />
        </TweakSection>
      </TweaksPanel>
    </React.Fragment>
  );
}

ReactDOM.createRoot(document.getElementById('root')).render(<App />);

